def check(actual, expected):
    # Answers within 1e-5 count as correct (lists are compared item by item).
    if isinstance(expected, list):
        return isinstance(actual, list) and len(actual) == len(expected) and all(map(check, actual, expected))
    try:
        return abs(float(actual) - expected) <= 1e-5
    except (TypeError, ValueError):
        return False
